INSERT INTO repo_cf_values (cf_value_id, education_level, sub_heading, text, status) VALUES ('CFV_SDG11_TVET_007', 'TVET', 'Environmental stewardship', 'Adopt eco-friendly practices in professional and personal contexts.', 'Active'), ('CFV_SDG11_TVET_008', 'TVET', 'Environmental stewardship', 'Support policies and practices that reduce waste and promote sustainability.', 'Active'), ('CFV_SDG11_TVET_009', 'TVET', 'Ethical and sustainable decision-making', 'Prioritise long-term sustainability over short-term gains.', 'Active'), ('CFV_SDG11_TVET_010', 'TVET', 'Ethical and sustainable decision-making', 'Choose eco-friendly materials and methods that reduce carbon footprints.', 'Active'), ('CFV_SDG11_TVET_011', 'TVET', 'Social equity and inclusivity', 'Promote inclusive urban development, ensuring access to housing, green spaces, and public transport for all.', 'Active'), ('CFV_SDG11_TVET_012', 'TVET', 'Social equity and inclusivity', 'Support projects and policies that address marginalised communities’ needs.', 'Active'), ('CFV_SDG11_TVET_013', 'TVET', 'Collaboration and collective action', 'Work across sectors and communities to achieve sustainability goals.', 'Active'), ('CFV_SDG11_TVET_014', 'TVET', 'Collaboration and collective action', 'Collaborate on projects like integrated waste management or urban greening initiatives.', 'Active'), ('CFV_SDG11_TVET_015', 'TVET', 'Engagement in recycling and circular economy', 'Understand the importance of recycling and resource conservation.', 'Active'), ('CFV_SDG11_TVET_016', 'TVET', 'Engagement in recycling and circular economy', 'Promote circular economy practices, including composting, waste sorting, and upcycling.', 'Active'), ('CFV_SDG11_TVET_017', 'TVET', 'Sustainability and alternative entrepreneurship', 'Commit to sustainability and support green business ventures.', 'Active'), ('CFV_SDG11_TVET_018', 'TVET', 'Sustainability and alternative entrepreneurship', 'Encourage innovative, eco-friendly entrepreneurial initiatives.', 'Active'), ('CFV_SDG11_TVET_019', 'TVET', 'Restoring the natural environment', 'Support ecosystem restoration and create urban buffer zones.', 'Active'), ('CFV_SDG11_TVET_020', 'TVET', 'Restoring the natural environment', 'Participate in reforestation, wetland rehabilitation, and green corridor development.', 'Active'), ('CFV_SDG11_TER_001', 'Tertiary education', 'Social responsibility and equity', 'Commit to providing inclusive housing and urban services for all, especially marginalised populations.', 'Active'), ('CFV_SDG11_TER_002', 'Tertiary education', 'Social responsibility and equity', 'Support policies that reduce inequality, promote social inclusion, and ensure equitable access to education, healthcare, and transport.', 'Active'), ('CFV_SDG11_TER_003', 'Tertiary education', 'Local and context-driven action', 'Recognise the importance of addressing local urban challenges with tailored, context-specific solutions.', 'Active'), ('CFV_SDG11_TER_004', 'Tertiary education', 'Local and context-driven action', 'Empower communities to co-design and implement strategies for issues like air pollution, flooding, or food insecurity.', 'Active'), ('CFV_SDG11_TER_005', 'Tertiary education', 'Cultural diversity and inclusion', 'Value and respect diverse cultures and identities in urban communities.', 'Active'), ('CFV_SDG11_TER_006', 'Tertiary education', 'Cultural diversity and inclusion', 'Promote intercultural understanding through festivals, art projects, and inclusive urban policies.', 'Active'), ('CFV_SDG11_TER_007', 'Tertiary education', 'Social and environmental justice', 'Advocate for policies that ensure fair access to clean air, water, housing, and public services.', 'Active'), ('CFV_SDG11_TER_008', 'Tertiary education', 'Social and environmental justice', 'Champion environmental equity and sustainable urban development that benefits vulnerable groups.', 'Active'), ('CFV_SDG11_TER_009', 'Tertiary education', 'Ethical leadership and accountability', 'Lead with integrity, ensuring transparent, accountable, and environmentally responsible urban planning.', 'Active'), ('CFV_SDG11_TER_010', 'Tertiary education', 'Ethical leadership and accountability', 'Prioritise long-term sustainability over short-term gains in urban development decisions.', 'Active'), ('CFV_SDG11_TER_011', 'Tertiary education', 'Collaboration and interdisciplinary engagement', 'Work across disciplines and sectors to address urban sustainability challenges.', 'Active'), ('CFV_SDG11_TER_012', 'Tertiary education', 'Collaboration and interdisciplinary engagement', 'Support multistakeholder partnerships for urban regeneration, climate adaptation, and resilient city planning.', 'Active'), ('CFV_SDG11_TER_013', 'Tertiary education', 'Critical thinking and problem solving', 'Apply holistic, data-driven approaches to complex urban systems, integrating social, economic, and environmental perspectives.', 'Active'), ('CFV_SDG11_TER_014', 'Tertiary education', 'Critical thinking and problem solving', 'Design innovative, sustainable policies that address urban challenges, such as pollution, transport, and infrastructure needs.', 'Active'), ('CFV_SDG11_TER_015', 'Tertiary education', 'Participatory urban planning', 'Engage communities and stakeholders in participatory planning to ensure inclusivity and alignment with urban residents’ needs.', 'Active'), ('CFV_SDG11_TER_016', 'Tertiary education', 'Participatory urban planning', 'Organise community workshops for feedback on urban regeneration projects, ensuring marginalised groups participate in decision-making.', 'Active'), ('CFV_SDG11_TER_017', 'Tertiary education', 'Participatory urban planning', 'Promote participatory policy frameworks that ensure transparent urban development and advocate for mechanisms giving marginalised communities a voice in urban planning.', 'Active'), ('CFV_SDG11_ADULT_001', 'Adult education', 'Environmental responsibility in housing and urban design', 'Commit to minimising environmental impact when acquiring shelter, constructing homes and designing living spaces.', 'Active'), ('CFV_SDG11_ADULT_002', 'Adult education', 'Environmental responsibility in housing and urban design', 'Recognise the role of sustainable materials, energy efficiency and green infrastructure in reducing ecological footprints.', 'Active'), ('CFV_SDG11_ADULT_003', 'Adult education', 'Environmental responsibility in housing and urban design', 'Choose energy-efficient housing, using recycled or locally sourced materials and integrating passive design principles to reduce reliance on artificial heating and cooling.', 'Active'), ('CFV_SDG11_ADULT_004', 'Adult education', 'Critical reflection on housing needs across life stages', 'Critically assess housing and shelter needs throughout various stages of life, considering cultural traditions, economic constraints, human resources and energy costs.', 'Active'), ('CFV_SDG11_ADULT_005', 'Adult education', 'Critical reflection on housing needs across life stages', 'Weigh the long-term affordability and sustainability of housing choices, such as selecting adaptable, multigenerational housing that accommodates changing family needs while remaining energy efficient.', 'Active'), ('CFV_SDG11_ADULT_006', 'Adult education', 'Commitment to community and social inclusion', 'Develop a strong sense of community, recognising the importance of collective wellbeing, inclusivity and social support in urban environments.', 'Active'), ('CFV_SDG11_ADULT_007', 'Adult education', 'Commitment to community and social inclusion', 'Support neighbourhood initiatives such as community gardens, local markets or shared public spaces that enable interaction and social cohesion.', 'Active'), ('CFV_SDG11_ADULT_008', 'Adult education', 'Active engagement in environmental and urban decision-making', 'Take an active role in decisions that impact the environment and urban habitat, advocating for policies and projects that promote sustainability.', 'Active'), ('CFV_SDG11_ADULT_009', 'Adult education', 'Active engagement in environmental and urban decision-making', 'Participate in town hall meetings, support green building codes or engage in local campaigns to improve waste management, public transportation or renewable energy adoption.', 'Active'), ('CFV_SDG11_ADULT_010', 'Adult education', 'Locally led urban climate adaptation', 'Recognise the value of locally driven, community-focused approaches to urban climate resilience, drawing on the unique knowledge, skills and lived experiences of residents.', 'Active'), ('CFV_SDG11_ADULT_011', 'Adult education', 'Locally led urban climate adaptation', 'Support grassroots initiatives such as rainwater harvesting projects, local flood mitigation strategies or neighbourhood tree-planting programmes to combat urban heat islands.', 'Active'), ('CFV_SDG11_ADULT_012', 'Adult education', 'Participation in urban planning and civic engagement', 'Believe in the power of civic participation to shape sustainable cities, understanding the impact of individual and collective actions on urban development.', 'Active'), ('CFV_SDG11_ADULT_013', 'Adult education', 'Participation in urban planning and civic engagement', 'Attend urban planning meetings, voice concerns about zoning changes, advocate for more green spaces and contribute ideas to local sustainability projects.', 'Active'), ('CFV_SDG11_ADULT_014', 'Adult education', 'Adaptability and lifelong learning', 'Cultivate an openness to innovative ideas, continuous learning and adaptability in the face of evolving urban sustainability challenges and emerging technologies.', 'Active'), ('CFV_SDG11_ADULT_015', 'Adult education', 'Adaptability and lifelong learning', 'Keep up to date with innovations in smart cities, renewable energy solutions and sustainable building practices, integrating these into real-world applications.', 'Active'), ('CFV_SDG11_ADULT_016', 'Adult education', 'Adaptability and lifelong learning', 'Promote policies that incentivise continuous professional development in urban sustainability fields and integrate emerging technologies into urban policy frameworks.', 'Active'), ('CFV_SDG12_SEC_001', 'Secondary education', 'Global citizenship', 'Awareness of shared responsibility in production and consumption.', 'Active'), ('CFV_SDG12_SEC_002', 'Secondary education', 'Global citizenship', 'Empathy for people affected by unsustainable systems, such as workers in low-wage manufacturing.', 'Active'), ('CFV_SDG12_SEC_003', 'Secondary education', 'Sustainability mindset', 'A sense of duty to reduce one’s environmental footprint and influence others through informed choices.', 'Active') ON CONFLICT DO NOTHING;